CREATE   PROCEDURE [synapse_ce].[usp_Insert_queueitem]
AS
BEGIN
	INSERT INTO [synapse_ce].[queueitem]
	(
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[enteredon],
		[exchangerate],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[msdyn_liveworkstreamid],
		[msdyn_liveworkstreamid_entitytype],
		[msdyn_liveworkstreamidname],
		[objectid],
		[objectid_entitytype],
		[objectidname],
		[objectidtypecode],
		[objecttypecode],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridtype],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[priority],
		[queueid],
		[queueid_entitytype],
		[queueidname],
		[queueitemid],
		[sender],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[state],
		[statecode],
		[status],
		[statuscode],
		[timezoneruleversionnumber],
		[title],
		[torecipients],
		[transactioncurrencyid],
		[transactioncurrencyid_entitytype],
		[transactioncurrencyidname],
		[utcconversiontimezonecode],
		[versionnumber],
		[workerid],
		[workerid_entitytype],
		[workeridmodifiedon],
		[workeridname],
		[workeridtype],
		[workeridyominame]
	)
	SELECT 
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[enteredon],
		stg.[exchangerate],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[msdyn_liveworkstreamid],
		stg.[msdyn_liveworkstreamid_entitytype],
		stg.[msdyn_liveworkstreamidname],
		stg.[objectid],
		stg.[objectid_entitytype],
		stg.[objectidname],
		stg.[objectidtypecode],
		stg.[objecttypecode],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridtype],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[priority],
		stg.[queueid],
		stg.[queueid_entitytype],
		stg.[queueidname],
		stg.[queueitemid],
		stg.[sender],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[state],
		stg.[statecode],
		stg.[status],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[title],
		stg.[torecipients],
		stg.[transactioncurrencyid],
		stg.[transactioncurrencyid_entitytype],
		stg.[transactioncurrencyidname],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber],
		stg.[workerid],
		stg.[workerid_entitytype],
		stg.[workeridmodifiedon],
		stg.[workeridname],
		stg.[workeridtype],
		stg.[workeridyominame]	
	FROM [staging_ce].[queueitem] stg
		LEFT JOIN [synapse_ce].[queueitem] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
